function validate([queries, pattern]) {
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100) return 'queries needs 1 to 100 words.';
  if (typeof pattern !== 'string' || pattern.length < 1 || pattern.length > 100) return 'pattern needs 1 to 100 letters.';
  if (!/^[A-Za-z]+$/.test(pattern)) return 'pattern may contain only English letters.';
  for (const q of queries) {
    if (typeof q !== 'string' || q.length < 1 || q.length > 100) return 'Each query has 1 to 100 letters.';
    if (!/^[A-Za-z]+$/.test(q)) return 'Queries may contain only English letters.';
  }
  return null;
}

