function camelMatch(queries, pattern) {
  const answer = [];
  for (const query of queries) {
    let matched = 0;
    let ok = true;
    for (let i = 0; i < query.length; i++) {
      const ch = query[i];
      if (matched < pattern.length && ch === pattern[matched]) {
        matched++;
      } else if (ch >= 'A' && ch <= 'Z') {
        ok = false;
        break;
      }
    }
    answer.push(ok && matched === pattern.length);
  }
  return answer;
}

