function camelMatch(queries, pattern) {
  const isLower = c => c === c.toLowerCase();
  return queries.map(q => {
    const n = q.length, m = pattern.length;
    // can[i][j]: q from i on can be built from pattern from j on.
    const can = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(false));
    can[n][m] = true;
    for (let i = n - 1; i >= 0; i--) {
      for (let j = m; j >= 0; j--) {
        let good = false;
        if (j < m && q[i] === pattern[j] && can[i + 1][j + 1]) good = true;
        if (isLower(q[i]) && can[i + 1][j]) good = true;
        can[i][j] = good;
      }
    }
    return can[0][0];
  });
}

