function generate(rand, size) {
  const pick = s => s[Math.floor(rand() * s.length)];
  const large = size === 'large';
  const letters = large ? 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ' : 'abAB';
  const lower = large ? 'abcdefghijklmnopqrstuvwxyz' : 'ab';
  const patternLength = large ? 20 + Math.floor(rand() * 30) : 1 + Math.floor(rand() * 4);
  let pattern = '';
  for (let i = 0; i < patternLength; i++) pattern += pick(letters);
  const count = large ? 100 : 1 + Math.floor(rand() * 5);
  const limit = large ? 100 : 8;
  const queries = [];
  for (let q = 0; q < count; q++) {
    let word = '';
    const style = rand();
    if (style < 0.6) {
      // Build from the pattern by inserting lowercase letters, sometimes with one mistake.
      for (const c of pattern) {
        while (rand() < (large ? 0.5 : 0.3) && word.length < limit - 1) word += pick(lower);
        word += c;
      }
      while (rand() < 0.3 && word.length < limit) word += pick(lower);
      if (rand() < 0.35) {
        const at = Math.floor(rand() * (word.length + 1));
        word = word.slice(0, at) + pick(letters) + word.slice(at);
      }
      word = word.slice(0, limit);
    } else {
      const length = 1 + Math.floor(rand() * limit);
      for (let i = 0; i < length; i++) word += pick(letters);
    }
    queries.push(word);
  }
  return [queries, pattern];
}
